pm.test("HOST login successful", function () {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

if (response.token) {
    pm.collectionVariables.set("hostToken", response.token);
    console.log("HOST token saved successfully.");
}

pm.test("PLAYER login successful", function () {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

if (response.token) {
    pm.collectionVariables.set("playerToken", response.token);
    console.log("PLAYER token saved successfully.");
}

pm.test("Kakashi HOST login successful", function () {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

if (response.token) {
    pm.collectionVariables.set("kakashiHostToken", response.token);
    console.log("Kakashi HOST token saved.");
}

pm.test("Registration returns 201", function () {
    pm.response.to.have.status(201);
});

const response = pm.response.json();

pm.test("Registration always creates PLAYER", function () {
    pm.expect(response.user.role).to.eql("PLAYER");
});

pm.test("Password hash is not exposed", function () {
    pm.expect(response.user).to.not.have.property("password_hash");
});

pm.test("Duplicate school ID returns 409", function () {
    pm.response.to.have.status(409);
});

pm.test("Error code is SCHOOL_ID_EXISTS", function () {
    const response = pm.response.json();
    pm.expect(response.error.code).to.eql("SCHOOL_ID_EXISTS");
});

pm.test("Duplicate email returns 409", function () {
    pm.response.to.have.status(409);
});

pm.test("Error code is EMAIL_EXISTS", function () {
    const response = pm.response.json();
    pm.expect(response.error.code).to.eql("EMAIL_EXISTS");
});

pm.test("Weak password returns 400", function () {
    pm.response.to.have.status(400);
});

pm.test("Validation error is returned", function () {
    const response = pm.response.json();
    pm.expect(response.error.code).to.eql("VALIDATION_FAILED");
});

pm.test("Wrong password returns 401", function () {
    pm.response.to.have.status(401);
});

const response = pm.response.json();

pm.test("Error code is INVALID_CREDENTIALS", function () {
    pm.expect(response.error.code).to.eql("INVALID_CREDENTIALS");
});

pm.collectionVariables.set("wrongLoginError", JSON.stringify(response));

pm.test("Unknown school ID returns 401", function () {
    pm.response.to.have.status(401);
});

const response = pm.response.json();

pm.test("Error code is INVALID_CREDENTIALS", function () {
    pm.expect(response.error.code).to.eql("INVALID_CREDENTIALS");
});

pm.test("Unknown and wrong login errors are identical", function () {
    pm.expect(JSON.stringify(response))
        .to.eql(pm.collectionVariables.get("wrongLoginError"));
});

pm.test("Valid token returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Authenticated user is HOST", function () {
    const response = pm.response.json();
    pm.expect(response.user.role).to.eql("HOST");
});

pm.test("Missing token returns 401", function () {
    pm.response.to.have.status(401);
});

pm.test("Error code is AUTH_REQUIRED", function () {
    const response = pm.response.json();
    pm.expect(response.error.code).to.eql("AUTH_REQUIRED");
});

pm.test("Changed token returns 401", function () {
    pm.response.to.have.status(401);
});

pm.test("Error code is INVALID_TOKEN", function () {
    const response = pm.response.json();
    pm.expect(response.error.code).to.eql("INVALID_TOKEN");
});

pm.test("X-Demo-User cannot authenticate", function () {
    pm.response.to.have.status(401);
});

pm.test("Authentication is required", function () {
    const response = pm.response.json();
    pm.expect(response.error.code).to.eql("AUTH_REQUIRED");
});

pm.test("PLAYER is forbidden from users endpoint", function () {
    pm.response.to.have.status(403);
});

pm.test("Error code is FORBIDDEN", function () {
    const response = pm.response.json();
    pm.expect(response.error.code).to.eql("FORBIDDEN");
});

pm.test("ADMIN can list users", function () {
    pm.response.to.have.status(200);
});

pm.test("Users are returned", function () {
    const response = pm.response.json();
    pm.expect(response.users).to.be.an("array");
    pm.expect(response.users.length).to.be.above(0);
});

pm.test("Password hashes are not exposed", function () {
    const response = pm.response.json();

    response.users.forEach(function (user) {
        pm.expect(user).to.not.have.property("password_hash");
    });
});

pm.test("ADMIN can promote PLAYER to HOST", function () {
    pm.response.to.have.status(200);
});

pm.test("User role is now HOST", function () {
    const response = pm.response.json();
    pm.expect(response.user.role).to.eql("HOST");
});

pm.test("ADMIN cannot change own role", function () {
    pm.response.to.have.status(409);
});

pm.test("Error code is CANNOT_CHANGE_OWN_ROLE", function () {
    const response = pm.response.json();
    pm.expect(response.error.code).to.eql("CANNOT_CHANGE_OWN_ROLE");
});

